/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
const dir = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '0', DB_PATH: join(dir, 'launch.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  const port = await new Promise((resolve, reject) => {
    let output = '';
    const timer = setTimeout(() => reject(new Error('Launch timeout')), 5000);
    child.stdout.on('data', data => { output += data; const match = output.match(/listening on port (\\d+)/); if (match) { clearTimeout(timer); resolve(match[1]); } });
    child.once('error', error => { clearTimeout(timer); reject(error); });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  if (response.status !== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health check failed');
  console.log('npm start: health check passed');
} finally {
  const ended = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await ended;
  await rm(dir, { recursive: true, force: true });
}
JS
